def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    # The camera gives a view of the course behind the trailer. Keep the trailer
    # aligned with the bay bearing when it is visible; otherwise stabilize hitch.
    target = obs.get('target', {}) or {}
    bearing = target.get('bearing_deg') if target.get('in_sight') else None
    steer = 1.25 * h
    if bearing is not None:
        # Convert bearing around straight back to signed course offset.
        off = ((float(bearing) - 180.0 + 180.0) % 360.0) - 180.0
        steer -= 0.45 * off
    steer = max(-18.0, min(18.0, steer))
    speed = -0.45 if abs(h) < 25.0 else -0.25
    if abs(h) > 42.0:
        speed = 0.0
    return (steer, speed, -23.0)

