def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    status = obs.get('status')
    # Clear the contacted rail by pulling forward slowly while straightening.
    # After the penalty, move forward enough to unpin, then stop for assessment.
    if status == 'PINNED' or obs.get('motion', {}).get('hold_s', 0) > 0:
        return (max(-12.0, min(12.0, -2.0*h)), 0.0, -23.0)
    if obs.get('progress', {}).get('covered', 0) < 11.0:
        return (max(-12.0, min(12.0, -2.0*h)), 0.55, -23.0)
    # Resume a very slow reverse with hitch feedback; contact occurred on the
    # trailer's right rear, so favor a modest leftward correction.
    steer = max(-10.0, min(10.0, 1.5*h + 2.0))
    return (steer, -0.25, -23.0)

