def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    cam = (obs.get('views', {}) or {}).get('camera', {}) or {}
    walls = cam.get('walls', []) or []
    right = [float(d) for b, d in walls if -160 <= float(b) <= -65]
    left = [float(d) for b, d in walls if 120 <= float(b) <= 180]
    # Move the trailer away from the nearer side, with a small hitch correction.
    bias = 0.0
    if right and left:
        bias = max(-4.0, min(4.0, 1.0 * (min(right) - min(left))))
    steer = max(-6.0, min(6.0, 1.5 * h + bias))
    return (steer, -0.18, -23.0)

