phase = 0
forward_until = None

def control(obs):
    global phase, forward_until
    t = obs.get('t', 0.0)
    hold = obs.get('motion', {}).get('hold_s', 0.0)
    h = obs.get('hitch_deg', 0.0)
    if phase == 0:
        if hold > 0:
            return (0.0, 0.0, 170.0)
        phase = 1
        forward_until = t + 2.8
    if phase == 1:
        if t < forward_until:
            return (0.0, 0.32, 170.0)
        phase = 2
        return (0.0, 0.0, 170.0)
    if hold > 0:
        return (0.0, 0.0, 170.0)
    steer = max(-16.0, min(12.0, -8.0 + 1.4 * h))
    speed = -0.24 if abs(h) < 15.0 else -0.12
    return (steer, speed, 170.0)

