def control(obs):
    h=float(obs.get('hitch_deg',0.0))
    status=obs.get('status','')
    if status=='PINNED' or abs(h)>12:
        # Forward recovery straightens the trailer; keep wheels right to clear the rear-right contact.
        return (-12.0, 0.45, -41.0)
    # Resume cautiously, correcting articulation toward zero.
    steer=max(-10.0,min(10.0,0.9*h))
    speed=-0.35 if abs(h)<8 else -0.2
    if abs(h)>25: speed=0.0
    return (steer,speed,-41.0)

